  //密码加密
  var decodePwd = '';
  try{
    //尝试解密
    decodePwd = V8.EncryptHelper.DESDecode(V8.Form.Pwd);
  }catch(e){
    //如果解密失败，就是明文
    decodePwd = V8.Form.Pwd;
  }
  //DES加密
  V8.Form.Pwd = V8.EncryptHelper.DESEncode(decodePwd);
}

