/*
 * V8 ApiEngine
 * ApiEngineKey: user-module-table-preference
 * Version: v1.0.4
 * Function:
 * - 按当前登录用户与模块读取或保存数据表格列显示偏好；采用稀疏差异记录，恢复默认时删除记录。
 */

var TABLE_NAME = 'rpt_user_module_setting';
var SETTING_TYPE = 'TableColumnVisibility';
var SCHEMA_VERSION = 1;
var MAX_KEYS = 512;
var MAX_KEY_LENGTH = 160;

var text = function (value) {
    return value === null || value === undefined ? '' : String(value).trim();
};

var fail = function (msg, code) {
    return { Code: code || 0, Msg: msg };
};

var ok = function (data, msg) {
    return { Code: 1, Data: data || {}, Msg: msg || '' };
};

var normalizeHiddenColumnKeys = function (value) {
    var source = value;
    if (typeof source == 'string') {
        try {
            var parsed = JSON.parse(source || '[]');
            source = parsed && parsed.HiddenColumnKeys ? parsed.HiddenColumnKeys : parsed;
        } catch (parseError) {
            source = [];
        }
    }
    if (!source || source.length === undefined || source.length === null) source = [];

    var result = [];
    var seen = {};
    for (var i = 0; i < source.length && result.length < MAX_KEYS; i++) {
        var key = text(source[i]);
        if (!key || key.length > MAX_KEY_LENGTH || !/^(field|audit):[A-Za-z0-9_.:-]+$/.test(key) || seen[key]) continue;
        seen[key] = true;
        result.push(key);
    }
