};

var currentUser = V8.CurrentUser || {};
var currentUserId = text(currentUser.Id || currentUser.UserId);
if (!currentUserId) return fail('登录状态已失效，请重新登录。', 1001);

var sysMenuId = text(V8.Param.SysMenuId || V8.Param.ModuleEngineKey);
if (!sysMenuId || sysMenuId.length > 50 || !/^[A-Za-z0-9_-]+$/.test(sysMenuId)) {
    return fail('SysMenuId 参数无效。');
}

// 只允许为真实模块保存偏好，避免垃圾键无限增长。
var menuResult = V8.FormEngine.GetFormData('sys_menu', {
    Id: sysMenuId,
    _SelectFields: ['Id', 'Name', 'DiyTableId']
});
if (menuResult.Code != 1) {
    return fail(menuResult.Code == 2 ? '模块不存在或已删除。' : (menuResult.Msg || '读取模块失败。'));
}

var rowIdSource = TABLE_NAME + '|' + text(V8.OsClient).toLowerCase() + '|' + currentUserId + '|' + sysMenuId + '|' + SETTING_TYPE;
var rowId = text(V8.EncryptHelper.MD5Encrypt(rowIdSource)).toLowerCase();
if (!rowId) return fail('无法生成用户模块设置标识。');

var action = text(V8.Param.Action || 'Get').toLowerCase();
if (action == 'get') {
    var getResult = V8.FormEngine.GetFormData(TABLE_NAME, {
        Id: rowId,
        _SelectFields: ['Id', 'OwnerUserId', 'SysMenuId', 'SettingType', 'SettingJson', 'SchemaVersion', 'UpdateTime']
    });
    if (getResult.Code == 2) {
        return ok({
            Version: SCHEMA_VERSION,
            SysMenuId: sysMenuId,
            HiddenColumnKeys: [],
            IsDefault: true
        });
    }
    if (getResult.Code != 1) return fail(getResult.Msg || '读取列设置失败。');
    var row = getResult.Data || {};
    if (text(row.OwnerUserId) != currentUserId || text(row.SysMenuId) != sysMenuId || text(row.SettingType) != SETTING_TYPE) {
        return fail('用户模块设置归属校验失败。');
    }
    var setting = {};
    try { setting = JSON.parse(text(row.SettingJson) || '{}'); } catch (settingError) { setting = {}; }
    return ok({
        Version: SCHEMA_VERSION,
        SysMenuId: sysMenuId,
        HiddenColumnKeys: normalizeHiddenColumnKeys(setting.HiddenColumnKeys),
        IsDefault: false,
        UpdateTime: row.UpdateTime || ''
    });
}

if (action != 'save') return fail('Action 仅支持 Get 或 Save。');
var hiddenColumnKeys = normalizeHiddenColumnKeys(V8.Param.HiddenColumnKeys);

// 恢复模块默认时删除差异行；没有改过的模块不会产生任何数据库记录。
if (hiddenColumnKeys.length == 0) {
    var existingResult = V8.FormEngine.GetFormData(TABLE_NAME, { Id: rowId, _SelectFields: ['Id', 'OwnerUserId'] });
    if (existingResult.Code == 2) {
        return ok({ Version: SCHEMA_VERSION, SysMenuId: sysMenuId, HiddenColumnKeys: [], IsDefault: true }, '已恢复模块默认列。');
    }
    if (existingResult.Code != 1) return fail(existingResult.Msg || '读取原列设置失败。');
    if (text(existingResult.Data.OwnerUserId) != currentUserId) return fail('用户模块设置归属校验失败。');
    var deleteResult = V8.FormEngine.DelFormData(TABLE_NAME, { Id: rowId });
    if (deleteResult.Code != 1 && deleteResult.Code != 2) return fail(deleteResult.Msg || '恢复模块默认列失败。');
    return ok({ Version: SCHEMA_VERSION, SysMenuId: sysMenuId, HiddenColumnKeys: [], IsDefault: true }, '已恢复模块默认列。');
}

var settingJson = JSON.stringify({
    Version: SCHEMA_VERSION,
    HiddenColumnKeys: hiddenColumnKeys
});
var saveData = {
    Id: rowId,
    OwnerUserId: currentUserId,
    SysMenuId: sysMenuId,
    SettingType: SETTING_TYPE,
    SettingJson: settingJson,
    SchemaVersion: SCHEMA_VERSION
};
var getStoredRowIncludingDeleted = function () {
    return V8.Db.FromSql(
        'SELECT Id, OwnerUserId, SysMenuId, SettingType, IsDeleted FROM ' + TABLE_NAME + ' WHERE Id = @p0'
    ).AddInParameter('@p0', rowId).First();
};
var validateStoredRowOwner = function (row) {
    return row
        && text(row.OwnerUserId) == currentUserId
        && text(row.SysMenuId) == sysMenuId
        && text(row.SettingType) == SETTING_TYPE;
};
var restoreStoredRow = function (row) {
    if (!validateStoredRowOwner(row)) return fail('用户模块设置归属校验失败。');
    var affected = V8.Db.FromSql(
        'UPDATE ' + TABLE_NAME
        + ' SET SettingJson = @p0, SchemaVersion = @p1, IsDeleted = @p2, UpdateTime = @p3'
        + ' WHERE Id = @p4 AND OwnerUserId = @p5 AND SysMenuId = @p6 AND SettingType = @p7'
    )
        .AddInParameter('@p0', settingJson)
        .AddInParameter('@p1', SCHEMA_VERSION)
        .AddInParameter('@p2', 0)
        .AddInParameter('@p3', DateNow('yyyy-MM-dd HH:mm:ss'))
        .AddInParameter('@p4', rowId)
        .AddInParameter('@p5', currentUserId)
        .AddInParameter('@p6', sysMenuId)
        .AddInParameter('@p7', SETTING_TYPE)
        .ExecuteNonQuery();
    return affected == 1 ? { Code: 1 } : fail('恢复列设置记录失败。');
};
var existingSaveResult = V8.FormEngine.GetFormData(TABLE_NAME, {
    Id: rowId,
    _SelectFields: ['Id', 'OwnerUserId', 'SysMenuId', 'SettingType']
