if (existingSaveResult.Code == 1) {
    if (text(existingSaveResult.Data.OwnerUserId) != currentUserId
        || text(existingSaveResult.Data.SysMenuId) != sysMenuId
        || text(existingSaveResult.Data.SettingType) != SETTING_TYPE) {
        return fail('用户模块设置归属校验失败。');
