        if (saveResult.Code != 1) {
            var concurrentRow = getStoredRowIncludingDeleted();
            if (concurrentRow && concurrentRow.Id) saveResult = restoreStoredRow(concurrentRow);
        }
    }
} else {
    return fail(existingSaveResult.Msg || '读取原列设置失败。');
}
if (saveResult.Code != 1) return fail(saveResult.Msg || '保存列设置失败。');

return ok({
    Version: SCHEMA_VERSION,
    SysMenuId: sysMenuId,
    HiddenColumnKeys: hiddenColumnKeys,
    IsDefault: false
}, '列设置已保存。');

