/*
 * V8 ApiEngine
 * ApiEngineKey: sys-user-security-action
 * Version: v1.0.1
 * Function:
 * - 仅系统管理员可执行的系统账号安全操作。Clear 动作清除目标用户全部终端登录信息并立即吊销所有 Token；Disable 动作先执行同一吊销逻辑，再将 sys_user.State 更新为 0。优先调用平台 ClearUserLoginInfo，旧服务使用在线终端 API 与 Redis 清理兼容回退，并写入安全审计日志。
 */

function parseHttpResult(value) {
  if (!value) return null;
  if (typeof value === "string") {
    try {
      return JSON.parse(value);
    } catch (ex) {
      return null;
    }
  }
  return value;
}

function clearUserLoginInfo(userId) {
  try {
    if (V8.Method.ClearUserLoginInfo) {
      return V8.Method.ClearUserLoginInfo(userId, V8.OsClient);
    }
  } catch (methodEx) {
    // 兼容尚未部署 ClearUserLoginInfo 的旧服务，继续执行现有能力回退。
  }

  var currentToken = V8.Method.GetCurrentToken();
  var token = currentToken && currentToken.Token ? currentToken.Token : "";
  var apiBase = V8.SysConfig && V8.SysConfig.ApiBase ? V8.SysConfig.ApiBase : "";
  var forcedTerminalCount = 0;
  if (apiBase && token) {
    var listResult = parseHttpResult(V8.Http.Post({
      Url: apiBase + "/api/OnlineTerminal/List",
      PostParam: { OsClient: V8.OsClient },
      ParamType: "json",
      Headers: {
        authorization: "Bearer " + token,
        osclient: V8.OsClient
      }
    }));
    var onlineUsers = listResult && listResult.Code == 1 && listResult.Data ? listResult.Data : [];
    var targetOnlineUser = null;
    for (var i = 0; i < onlineUsers.length; i++) {
      if (String(onlineUsers[i].UserId || "") === userId) {
        targetOnlineUser = onlineUsers[i];
        break;
      }
    }
    var terminals = targetOnlineUser && targetOnlineUser.Terminals ? targetOnlineUser.Terminals : [];
    for (var j = 0; j < terminals.length; j++) {
      var connectionId = terminals[j] && terminals[j].ConnectionId ? terminals[j].ConnectionId : "";
      if (!connectionId || connectionId.indexOf("token:") === 0) continue;
      var kickResult = parseHttpResult(V8.Http.Post({
        Url: apiBase + "/api/OnlineTerminal/Kick",
        PostParam: {
          OsClient: V8.OsClient,
          UserId: userId,
          ConnectionId: connectionId
        },
        ParamType: "json",
        Headers: {
          authorization: "Bearer " + token,
          osclient: V8.OsClient
        }
      }));
      if (kickResult && kickResult.Code == 1) {
        forcedTerminalCount++;
      }
    }
  }

  var loginTokenKey = "Microi:" + V8.OsClient + ":LoginTokenSysUser:" + userId;
  var hadLoginToken = V8.Cache.KeyExist(loginTokenKey);
  V8.Cache.Remove(loginTokenKey);
  V8.Cache.Remove("Microi:" + V8.OsClient + ":ChatOnline:" + userId);
  V8.Cache.HashDelete("Microi:" + V8.OsClient + ":OnlineUsers", userId);
  return {
    Code: 1,
    Data: {
      UserId: userId,
      RevokedTokenCount: hadLoginToken ? 1 : 0,
      ForcedTerminalCount: forcedTerminalCount,
      CompatibilityFallback: true
    },
    Msg: "用户所有终端登录信息已清除。"
  };
}

var currentUser = V8.CurrentUser || {};
var isAdmin = currentUser._IsAdmin === true || Number(currentUser.Level || 0) >= 9999;
if (!isAdmin) {
  return { Code: 0, Msg: "仅系统管理员可执行用户登录安全操作。" };
}

var userId = String(V8.Param.UserId || V8.Param.Id || "").trim();
var action = String(V8.Param.Action || "Clear").trim();
if (!userId) {
  return { Code: 0, Msg: "用户Id不能为空。" };
}
if (action !== "Clear" && action !== "Disable") {
  return { Code: 0, Msg: "不支持的操作类型。" };
}

var userResult = V8.FormEngine.GetFormData("sys_user", {
  Id: userId,
  _SelectFields: ["Id", "Account", "Name", "State"]
});
if (!userResult || userResult.Code != 1 || !userResult.Data) {
  return { Code: 0, Msg: (userResult && userResult.Msg) || "目标用户不存在。" };
}

var targetUser = userResult.Data;
var clearResult = clearUserLoginInfo(userId);
if (!clearResult || clearResult.Code != 1) {
  return clearResult || { Code: 0, Msg: "清除登录信息失败。" };
}

if (action === "Disable") {
  var disableResult = V8.FormEngine.UptFormData("sys_user", {
    Id: userId,
    State: 0,
    _InvokeType: "Client"
  });
  if (!disableResult || disableResult.Code != 1) {
    return disableResult || { Code: 0, Msg: "用户禁用失败。" };
  }
}

V8.Method.AddSysLog({
  Type: "安全审计",
  Title: action === "Disable" ? "禁止系统账号" : "清除用户登录信息",
  Content: JSON.stringify({
    OperatorId: currentUser.Id || "",
    OperatorName: currentUser.Name || currentUser.Account || "",
    TargetUserId: userId,
    TargetAccount: targetUser.Account || "",
    Action: action,
    Time: DateNow("yyyy-MM-dd HH:mm:ss")
  }),
  Level: 2
});

return {
  Code: 1,
  Data: {
    UserId: userId,
    Account: targetUser.Account || "",
    State: action === "Disable" ? 0 : targetUser.State,
    RevokedTokenCount: clearResult.Data ? clearResult.Data.RevokedTokenCount : 0,
    ForcedTerminalCount: clearResult.Data ? clearResult.Data.ForcedTerminalCount : 0
  },
  Msg: action === "Disable"
    ? "该账号已禁止，所有终端登录信息和Token均已失效。"
    : "该用户所有终端登录信息和Token均已失效。"
};

